BEGIN;
SET LOCAL statement_timeout='120s';
CREATE TABLE IF NOT EXISTS public.ph_nursery_locations (location_code text PRIMARY KEY,block_alpha text,block_number integer,house_orientation text,permanent_shade text,house_count integer,total_beds numeric,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_nursery_locations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_nursery_locations FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_nursery_locations TO service_role;
