ALTER TABLE public.ph_nursery_items_cpb ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_nursery_items_cpb FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_nursery_items_cpb TO service_role;
CREATE TABLE IF NOT EXISTS public.ph_nursery_water_rating (id bigserial PRIMARY KEY,genus text,botanical_name text,common_name text,sort_name text,water_rank numeric,water_tier text,hydro_zone text,schedule_flag text,dwu_1 text,dwu_2 text,dwu_3 text,dwu_5 text,dwu_7 text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_nursery_water_rating ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_nursery_water_rating FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_nursery_water_rating TO service_role;
CREATE TABLE IF NOT EXISTS public.ph_scientific_evidence_log (id bigserial PRIMARY KEY,genus text,water_rank numeric,water_tier text,hydro_zone text,schedule_flag text,dwu_1 text,dwu_2 text,dwu_3 text,dwu_5 text,dwu_7 text,evidence_notes text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_scientific_evidence_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_scientific_evidence_log FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_scientific_evidence_log TO service_role;
CREATE TABLE IF NOT EXISTS public.ph_header_control (id bigserial PRIMARY KEY,source_tab text,col_letter text,col_index integer,raw_header_text text,live_sample_values text,assigned_category_dropdown text,standardized_field_name text,managing_gem text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_header_control ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_header_control FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_header_control TO service_role;
CREATE TABLE IF NOT EXISTS public.ph_prod_schedule_active (id bigserial PRIMARY KEY,source_tab_name text DEFAULT 'PROD SCHEDULE 102726 (2026-10-29_1232)',line_id text,itemcode text,commonname text,contsize text,source text,planned_qty numeric,req_qty numeric,cutoff_qty numeric,cpb numeric,beds_needed numeric,target_loc text,tier_label text,plant_date text,can_fill_date text,staged_from text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_prod_schedule_active ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_prod_schedule_active FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_prod_schedule_active TO service_role;
CREATE TABLE IF NOT EXISTS public.ph_dylan_decisions_store (plan_id text PRIMARY KEY,decision text DEFAULT '✅ APPROVE',override_loc text DEFAULT '',override_qty numeric,notes text DEFAULT '',is_custom text DEFAULT 'N',wf_type text,itemcode text,commonname text,contsize text,lot_date text,from_loc text,crew_done boolean DEFAULT false,updated_by text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.ph_dylan_decisions_store ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ph_dylan_decisions_store FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.ph_dylan_decisions_store TO service_role;
ALTER TABLE public.user_access ADD COLUMN IF NOT EXISTS view_nursery_command_tables text NOT NULL DEFAULT 'N' CHECK(view_nursery_command_tables IN ('Y','N'));
UPDATE public.user_access SET view_nursery_command_tables=CASE WHEN username='dylan_collyge' THEN 'Y' ELSE 'N' END,
 view_permissions=view_permissions||jsonb_build_object('view_nursery_command_tables',CASE WHEN username='dylan_collyge' THEN 'Y' ELSE 'N' END)
 WHERE NOT view_permissions ? 'view_nursery_command_tables';
CREATE OR REPLACE FUNCTION private.sync_nursery_capability_v23127() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  NEW.view_nursery_command_tables:=coalesce(NEW.view_permissions->>'view_nursery_command_tables',CASE WHEN NEW.username='dylan_collyge' THEN 'Y' ELSE 'N' END);
 ELSIF NEW.view_permissions->>'view_nursery_command_tables' IS DISTINCT FROM OLD.view_permissions->>'view_nursery_command_tables' THEN
  NEW.view_nursery_command_tables:=coalesce(NEW.view_permissions->>'view_nursery_command_tables','N');
 END IF;
 NEW.view_permissions:=NEW.view_permissions||jsonb_build_object('view_nursery_command_tables',NEW.view_nursery_command_tables);
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS nursery_capability_v23127 ON public.user_access;
CREATE TRIGGER nursery_capability_v23127 BEFORE INSERT OR UPDATE ON public.user_access FOR EACH ROW EXECUTE FUNCTION private.sync_nursery_capability_v23127();
-- Extend the canonical per-user/per-role command without replacing its concurrency,
-- authorization, alias, event, or idempotency behavior.
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.save_access_permission_v23127(uuid,text,text,text,text,uuid,bigint)'::regprocedure) INTO definition;
 IF position('view_nursery_command_tables' IN definition)=0 THEN
  definition:=replace(definition,'''view_flyers'',''view_comm''','''view_flyers'',''view_comm'',''view_nursery_command_tables''');
  IF position('view_nursery_command_tables' IN definition)=0 THEN RAISE EXCEPTION 'NURSERY_CANONICAL_PERMISSION_PATCH_MISSING'; END IF;
  EXECUTE definition;
 END IF;
END $$;
CREATE TABLE IF NOT EXISTS private.nursery_commands_v23127(actor_id uuid NOT NULL,command_id uuid NOT NULL,input jsonb NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,command_id));
REVOKE ALL ON private.nursery_commands_v23127 FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.nursery_command_v23127(p_table text,p_operation text,p_payload jsonb DEFAULT '{}') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor public.profiles; table_name text; key_name text; key_value text; allowed text[]; columns_sql text; values_sql text; updates_sql text; input_row jsonb; previous jsonb; result jsonb; receipt private.nursery_commands_v23127; v_command_id uuid; input jsonb; page_offset integer; page_limit integer;
BEGIN
 actor:=private.current_active_profile();
 IF actor.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_access u WHERE u.profile_id=actor.id AND u.view_nursery_command_tables='Y' AND u.view_permissions->>'view_nursery_command_tables'='Y') THEN RAISE EXCEPTION 'NURSERY_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 IF p_table IS NULL OR p_table<>ALL(ARRAY['ph_nursery_locations','ph_nursery_items_cpb','ph_nursery_water_rating','ph_scientific_evidence_log','ph_header_control','ph_prod_schedule_active','ph_dylan_decisions_store']) THEN RAISE EXCEPTION 'NURSERY_TABLE_INVALID' USING ERRCODE='22023'; END IF;
 table_name:=p_table;
 key_name:=CASE p_table WHEN 'ph_nursery_locations' THEN 'location_code' WHEN 'ph_nursery_items_cpb' THEN 'itemcode' WHEN 'ph_dylan_decisions_store' THEN 'plan_id' ELSE 'id' END;
 IF p_operation='read' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k<>ALL(ARRAY['offset','limit'])) THEN RAISE EXCEPTION 'NURSERY_READ_INVALID' USING ERRCODE='22023'; END IF;
  page_offset:=greatest(0,least(200000,coalesce((p_payload->>'offset')::integer,0)));page_limit:=greatest(1,least(1000,coalesce((p_payload->>'limit')::integer,1000)));
  EXECUTE format('SELECT jsonb_build_object(''rows'',coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb)) FROM (SELECT * FROM public.%I ORDER BY %I LIMIT $1 OFFSET $2) r',table_name,key_name) INTO result USING page_limit,page_offset;
  RETURN result;
 END IF;
 IF p_operation IS DISTINCT FROM 'save' OR jsonb_typeof(p_payload->'row') IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>65536 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k<>ALL(ARRAY['row','expectedUpdatedAt','commandId'])) THEN RAISE EXCEPTION 'NURSERY_SAVE_INVALID' USING ERRCODE='22023'; END IF;
 v_command_id:=(p_payload->>'commandId')::uuid;IF v_command_id IS NULL THEN RAISE EXCEPTION 'NURSERY_COMMAND_REQUIRED' USING ERRCODE='22023';END IF;
 input:=jsonb_build_object('table',p_table,'payload',p_payload);
 PERFORM pg_advisory_xact_lock(hashtextextended('nursery-command:'||actor.id||':'||v_command_id,0));
 SELECT * INTO receipt FROM private.nursery_commands_v23127 WHERE actor_id=actor.id AND nursery_commands_v23127.command_id=v_command_id;
 IF FOUND THEN IF receipt.input<>input THEN RAISE EXCEPTION 'NURSERY_COMMAND_CONFLICT' USING ERRCODE='40001'; END IF;RETURN receipt.response; END IF;
 SELECT array_agg(a.attname::text) INTO allowed FROM pg_attribute a WHERE a.attrelid=format('public.%I',table_name)::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attname NOT IN ('updated_at','updated_by');
 input_row:=p_payload->'row';
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(input_row) k WHERE NOT k=ANY(allowed)) THEN RAISE EXCEPTION 'NURSERY_FIELD_INVALID' USING ERRCODE='22023';END IF;
 key_value:=input_row->>key_name;IF key_value IS NULL OR btrim(key_value)='' THEN RAISE EXCEPTION 'NURSERY_ROW_ID_REQUIRED' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('nursery-row:'||table_name||':'||key_value,0));
 EXECUTE format('SELECT to_jsonb(r) FROM public.%I r WHERE %I::text=$1 FOR UPDATE',table_name,key_name) INTO previous USING key_value;
 IF previous IS NOT NULL AND (p_payload->>'expectedUpdatedAt')::timestamptz IS DISTINCT FROM (previous->>'updated_at')::timestamptz THEN RAISE EXCEPTION 'NURSERY_REVISION_CONFLICT' USING ERRCODE='40001';END IF;
 IF previous IS NULL AND (table_name<>'ph_dylan_decisions_store' OR p_payload->>'expectedUpdatedAt' IS NOT NULL) THEN RAISE EXCEPTION 'NURSERY_ROW_NOT_FOUND' USING ERRCODE='22023';END IF;
 IF table_name='ph_dylan_decisions_store' THEN
  IF coalesce(input_row->>'decision','')<>ALL(ARRAY['✅ APPROVE','🔧 MODIFY / BUILD ON','❌ REMOVE','➕ ADD TO PLAN','⏳ HOLD / ANCHOR']) THEN RAISE EXCEPTION 'NURSERY_DECISION_INVALID' USING ERRCODE='22023';END IF;
  IF coalesce(input_row->>'override_loc','')<>'' AND NOT EXISTS(SELECT 1 FROM public.ph_nursery_locations WHERE location_code=input_row->>'override_loc') THEN RAISE EXCEPTION 'NURSERY_LOCATION_INVALID' USING ERRCODE='22023';END IF;
  IF coalesce((input_row->>'override_qty')::numeric,0)<0 THEN RAISE EXCEPTION 'NURSERY_QUANTITY_INVALID' USING ERRCODE='22023';END IF;
  input_row:=input_row||jsonb_build_object('updated_by',actor.username);
 END IF;
 input_row:=input_row||jsonb_build_object('updated_at',clock_timestamp());
 SELECT string_agg(format('%I',k),',' ORDER BY k),string_agg(format('r.%I',k),',' ORDER BY k),string_agg(format('%I=excluded.%I',k,k),',' ORDER BY k) FILTER(WHERE k<>key_name) INTO columns_sql,values_sql,updates_sql FROM jsonb_object_keys(input_row) k;
 EXECUTE format('INSERT INTO public.%I AS target (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) r ON CONFLICT (%I) DO UPDATE SET %s RETURNING to_jsonb(target)',table_name,columns_sql,values_sql,table_name,key_name,updates_sql) INTO result USING input_row;
 result:=jsonb_build_object('row',result,'commandId',v_command_id,'committed',true);
 INSERT INTO private.nursery_commands_v23127(actor_id,command_id,input,response) VALUES(actor.id,v_command_id,input,result);
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.nursery_command_v23127(text,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.nursery_command_v23127(text,text,jsonb) TO authenticated;
CREATE TABLE IF NOT EXISTS private.nursery_schedule_imports_v23127(file_key text PRIMARY KEY,file_name text NOT NULL,next_offset integer NOT NULL DEFAULT 0,complete boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false,headers jsonb NOT NULL DEFAULT '[]',rows_published integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS private.nursery_schedule_stage_v23127(file_key text NOT NULL REFERENCES private.nursery_schedule_imports_v23127(file_key),slice_offset integer NOT NULL,row_number integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(file_key,slice_offset,row_number));
REVOKE ALL ON private.nursery_schedule_imports_v23127,private.nursery_schedule_stage_v23127 FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.nursery_schedule_import_v23127(p_operation text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_variable
<<nursery_import>>
DECLARE file_key text:=p_payload->>'fileKey'; receipt private.nursery_schedule_imports_v23127; row_count integer; slice_offset integer; next_offset integer;
BEGIN
 IF NOT private.is_service_role_request() THEN RAISE EXCEPTION 'NURSERY_IMPORT_SERVICE_REQUIRED' USING ERRCODE='42501';END IF;
 IF file_key IS NULL OR length(file_key)>300 OR octet_length(p_payload::text)>67108864 THEN RAISE EXCEPTION 'NURSERY_IMPORT_INVALID' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('nursery-import:'||file_key,0));
 SELECT * INTO receipt FROM private.nursery_schedule_imports_v23127 i WHERE i.file_key=nursery_import.file_key FOR UPDATE;
 IF p_operation='status' THEN RETURN jsonb_build_object('published',coalesce(receipt.published,false),'rows',coalesce(receipt.rows_published,0));END IF;
 IF receipt.published THEN RETURN jsonb_build_object('published',true,'rows',receipt.rows_published);END IF;
 IF p_operation='append' THEN
  slice_offset:=(p_payload->>'offset')::integer;next_offset:=(p_payload->>'nextOffset')::integer;
  IF slice_offset<0 OR next_offset<slice_offset OR next_offset-slice_offset>1500 OR jsonb_typeof(p_payload->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'rows')>1500 THEN RAISE EXCEPTION 'NURSERY_SLICE_INVALID' USING ERRCODE='22023';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'rows') r WHERE position('10' IN coalesce(r->>'_warehouse',''))=0 OR coalesce(r->>'itemcode','')!~'^[0-9]{4,}\.[0-9A-Za-z]+\.[0-9A-Za-z]+$') THEN RAISE EXCEPTION 'NURSERY_WAREHOUSE_INVALID' USING ERRCODE='22023';END IF;
  IF receipt.file_key IS NULL THEN
   IF slice_offset<>0 THEN RAISE EXCEPTION 'NURSERY_SLICE_GAP' USING ERRCODE='40001';END IF;
   INSERT INTO private.nursery_schedule_imports_v23127(file_key,file_name,headers) VALUES(file_key,coalesce(p_payload->>'fileName',''),coalesce(p_payload->'headers','[]')) RETURNING * INTO receipt;
  END IF;
  IF receipt.next_offset>slice_offset THEN RETURN jsonb_build_object('nextOffset',receipt.next_offset);END IF;
  IF receipt.next_offset<>slice_offset THEN RAISE EXCEPTION 'NURSERY_SLICE_GAP' USING ERRCODE='40001';END IF;
  INSERT INTO private.nursery_schedule_stage_v23127(file_key,slice_offset,row_number,payload) SELECT file_key,slice_offset,ordinality::integer,value-'_warehouse' FROM jsonb_array_elements(p_payload->'rows') WITH ORDINALITY;
  UPDATE private.nursery_schedule_imports_v23127 i SET next_offset=nursery_import.next_offset,complete=coalesce((p_payload->>'done')::boolean,false),updated_at=clock_timestamp() WHERE i.file_key=nursery_import.file_key;
  RETURN jsonb_build_object('nextOffset',next_offset);
 END IF;
 IF p_operation IS DISTINCT FROM 'publish' OR NOT coalesce(receipt.complete,false) THEN RAISE EXCEPTION 'NURSERY_IMPORT_NOT_COMPLETE' USING ERRCODE='22023';END IF;
 SELECT count(*) INTO row_count FROM private.nursery_schedule_stage_v23127 s WHERE s.file_key=nursery_import.file_key;
 IF row_count=0 THEN RAISE EXCEPTION 'NURSERY_IMPORT_NO_PARK_HILL_ROWS' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('nursery-active-publication',0));
 DELETE FROM public.ph_prod_schedule_active;
 INSERT INTO public.ph_prod_schedule_active(source_tab_name,line_id,itemcode,commonname,contsize,source,planned_qty,req_qty,cutoff_qty,cpb,beds_needed,target_loc,tier_label,plant_date,can_fill_date,staged_from)
 SELECT r.source_tab_name,r.line_id,r.itemcode,r.commonname,r.contsize,r.source,r.planned_qty,r.req_qty,r.cutoff_qty,coalesce(c.cpb,r.cpb),CASE WHEN coalesce(c.cpb,r.cpb)>0 THEN r.planned_qty/coalesce(c.cpb,r.cpb) ELSE r.beds_needed END,r.target_loc,r.tier_label,r.plant_date,r.can_fill_date,r.staged_from
 FROM private.nursery_schedule_stage_v23127 s CROSS JOIN LATERAL jsonb_populate_record(NULL::public.ph_prod_schedule_active,s.payload) r LEFT JOIN public.ph_nursery_items_cpb c ON c.itemcode=r.itemcode WHERE s.file_key=nursery_import.file_key ORDER BY s.slice_offset,s.row_number;
 PERFORM private.resolve_nursery_schedule_locations_v23127();
 DELETE FROM public.ph_header_control WHERE source_tab='PROD SCHEDULE 102726 (2026-10-29_1232)';
 INSERT INTO public.ph_header_control(source_tab,col_letter,col_index,raw_header_text,live_sample_values,assigned_category_dropdown,standardized_field_name,managing_gem)
 SELECT source_tab,col_letter,col_index,raw_header_text,live_sample_values,assigned_category_dropdown,standardized_field_name,managing_gem FROM jsonb_populate_recordset(NULL::public.ph_header_control,receipt.headers);
 UPDATE private.nursery_schedule_imports_v23127 i SET published=true,rows_published=row_count,updated_at=clock_timestamp() WHERE i.file_key=nursery_import.file_key;
 DELETE FROM private.nursery_schedule_stage_v23127 s WHERE s.file_key=nursery_import.file_key;
 RETURN jsonb_build_object('published',true,'rows',row_count);
END $$;
REVOKE ALL ON FUNCTION public.nursery_schedule_import_v23127(text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.nursery_schedule_import_v23127(text,jsonb) TO service_role;

CREATE OR REPLACE FUNCTION private.nursery_name_key_v23127(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT coalesce(string_agg(word,' ' ORDER BY word),'') FROM regexp_split_to_table(trim(regexp_replace(lower(coalesce(value,'')),'[^a-z0-9]+',' ','g')),'\s+') word WHERE word<>'' $$;
CREATE INDEX IF NOT EXISTS ph_nursery_water_name_key_v23127 ON public.ph_nursery_water_rating(private.nursery_name_key_v23127(common_name));
CREATE INDEX IF NOT EXISTS ph_nursery_water_common_v23127 ON public.ph_nursery_water_rating(lower(common_name));
-- Four conservative fallback tiers. Unproven compatibility never invents a target.
-- This private set-based stock snapshot is used only during atomic publication.
CREATE OR REPLACE FUNCTION private.resolve_nursery_schedule_locations_v23127() RETURNS integer
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE scheduled record; chosen record; demand numeric; zone text; crop_year text; crop_season text; resolved integer:=0;
BEGIN
 CREATE TEMP TABLE nursery_stock_v23127 ON COMMIT DROP AS
 SELECT i.itemcode,regexp_replace(upper(i.locationcode),'^([A-L])\.([0-9]{2})\..*$','\1.\2.000') location_code,
  coalesce(i.source,'') source,coalesce(i.saleyear::text,'') sales_year,coalesce(i.season,'') season,
  max(w.hydro_zone) hydro_zone,
  sum(greatest(0,coalesce(nullif(regexp_replace(i.ptronhand::text,'[^0-9.-]','','g'),''),'0')::numeric)) quantity,
  sum(CASE WHEN c.cpb>0 THEN greatest(0,coalesce(nullif(regexp_replace(i.ptronhand::text,'[^0-9.-]','','g'),''),'0')::numeric)/c.cpb ELSE 0 END) beds,
  bool_or(c.cpb IS NULL OR c.cpb<=0) unknown_cpb
 FROM public.ph_master_inventory i LEFT JOIN public.ph_nursery_items_cpb c ON c.itemcode=i.itemcode
 LEFT JOIN LATERAL (SELECT water.hydro_zone FROM public.ph_nursery_water_rating water WHERE private.nursery_name_key_v23127(water.common_name)=private.nursery_name_key_v23127(i.commonname) ORDER BY water.id LIMIT 1) w ON true
 WHERE position('10' IN coalesce(i.warehousei::text,i.warehouseid::text,''))>0 AND i.locationcode~'^[A-L]\.[0-9]{2}\.'
 GROUP BY i.itemcode,regexp_replace(upper(i.locationcode),'^([A-L])\.([0-9]{2})\..*$','\1.\2.000'),coalesce(i.source,''),coalesce(i.saleyear::text,''),coalesce(i.season,'');
 CREATE INDEX ON nursery_stock_v23127(itemcode,location_code);
 CREATE INDEX ON nursery_stock_v23127(location_code,hydro_zone);
 CREATE TEMP TABLE nursery_capacity_v23127 ON COMMIT DROP AS
 SELECT l.*,CASE WHEN coalesce(bool_or(s.unknown_cpb),false) THEN 0 ELSE greatest(0,l.total_beds-coalesce(sum(s.beds),0)) END open_beds
 FROM public.ph_nursery_locations l LEFT JOIN pg_temp.nursery_stock_v23127 s USING(location_code) GROUP BY l.location_code;
 CREATE UNIQUE INDEX ON nursery_capacity_v23127(location_code);
 FOR scheduled IN SELECT p.* FROM public.ph_prod_schedule_active p ORDER BY p.plant_date,p.line_id,p.id LOOP
  demand:=CASE WHEN scheduled.cpb>0 THEN greatest(0,coalesce(scheduled.cutoff_qty,scheduled.planned_qty,0))/scheduled.cpb END;
  IF demand IS NULL OR demand<=0 THEN CONTINUE;END IF;
  crop_year:=coalesce('20'||substring(scheduled.line_id from '^\.([0-9]{2})\.'),substring(scheduled.plant_date from '(20[0-9]{2})'));crop_season:='F1';
  SELECT water.hydro_zone INTO zone FROM public.ph_nursery_water_rating water WHERE private.nursery_name_key_v23127(water.common_name)=private.nursery_name_key_v23127(scheduled.commonname) ORDER BY water.id LIMIT 1;
  SELECT c.location_code,1 tier INTO chosen FROM pg_temp.nursery_capacity_v23127 c WHERE c.location_code=scheduled.target_loc AND scheduled.tier_label LIKE 'Tier 1%' AND c.open_beds>=demand;
  IF NOT FOUND AND zone IS NOT NULL AND scheduled.source NOT IN ('','>') AND crop_year IS NOT NULL THEN
   SELECT c.location_code,
    CASE WHEN bool_or(s.itemcode=scheduled.itemcode AND s.source=scheduled.source AND s.season=crop_season AND right(s.sales_year,2)=right(crop_year,2)) THEN 2
         WHEN bool_or(s.itemcode=scheduled.itemcode AND s.source=scheduled.source AND right(s.sales_year,2)=right(crop_year,2)) THEN 3 ELSE 4 END tier
    INTO chosen FROM pg_temp.nursery_capacity_v23127 c JOIN pg_temp.nursery_stock_v23127 s USING(location_code)
    WHERE c.open_beds>=demand AND s.quantity>0 AND s.season<>'Y' AND s.hydro_zone=zone AND right(s.sales_year,2)=right(crop_year,2)
      AND EXISTS(SELECT 1 FROM pg_temp.nursery_stock_v23127 prior JOIN public.ph_nursery_locations original USING(location_code) WHERE prior.itemcode=scheduled.itemcode AND original.permanent_shade=c.permanent_shade AND original.house_orientation=c.house_orientation)
    GROUP BY c.location_code ORDER BY tier,sum(s.quantity) FILTER(WHERE s.itemcode=scheduled.itemcode) DESC NULLS LAST,c.location_code LIMIT 1;
  END IF;
  IF chosen.location_code IS NOT NULL THEN
   UPDATE public.ph_prod_schedule_active SET target_loc=chosen.location_code,tier_label=CASE chosen.tier WHEN 1 THEN 'Tier 1 — explicit schedule location' WHEN 2 THEN 'Tier 2 — same item, source and active season' WHEN 3 THEN 'Tier 3 — same item, source and sales year' ELSE 'Tier 4 — compatible sales-year block rotation' END,beds_needed=demand WHERE id=scheduled.id;
   UPDATE pg_temp.nursery_capacity_v23127 SET open_beds=open_beds-demand WHERE location_code=chosen.location_code;
   resolved:=resolved+1;
  ELSE UPDATE public.ph_prod_schedule_active SET target_loc='',tier_label='HOLD — no proven compatible capacity' WHERE id=scheduled.id;
  END IF;
 END LOOP;
 RETURN resolved;
END $$;
REVOKE ALL ON FUNCTION private.resolve_nursery_schedule_locations_v23127() FROM PUBLIC,anon,authenticated;

create or replace function private.operational_erp_status_v23120(p_status jsonb,p_started timestamptz,p_stamp timestamptz)
returns jsonb language plpgsql immutable set search_path='' as $$
declare source_key text; progress jsonb; receipt jsonb; amount numeric; total numeric:=0; all_done boolean:=true; checked boolean;
begin
  foreach source_key in array (array['drive','cav','reserves','soc','hl_po_parsed']||case when p_status->'sourceProgress' ? 'prod_schedule' then array['prod_schedule'] else array[]::text[] end) loop
    progress:=coalesce(p_status->'sourceProgress'->source_key,case when source_key='hl_po_parsed' then p_status->'sourceProgress'->'hl_po' end,'{}');
    select r into receipt from jsonb_array_elements(coalesce(p_status->'stageResults','[]')) with ordinality e(r,n)
      where r->>'key'=source_key and (nullif(progress->>'fileName','') is null or nullif(r->>'sourceFileName','') is null or r->>'sourceFileName'=progress->>'fileName') order by n desc limit 1;
    checked:=coalesce((progress->>'checked')::boolean,false) and progress->>'stage'='complete' or coalesce(receipt->>'outcome'='UP_TO_DATE',false);
    amount:=greatest(0,least(95,coalesce((progress->>'percent')::numeric,0)));
    if coalesce(progress->>'error','')<>'' or receipt->>'outcome'='failed' then checked:=false;
    elsif checked or (receipt->>'outcome' in ('processed','imported') and coalesce((receipt->>'rowCount')::numeric,0)>0)
      or (progress->>'publicationConfirmed'='true' and progress->>'publishedFileName'=progress->>'fileName' and coalesce((progress->>'rowsPublished')::numeric,0)>0) then amount:=100;
    end if;
    total:=total+amount;all_done:=all_done and coalesce(checked,false) and amount=100;
  end loop;
  if all_done then
    return p_status||jsonb_build_object('active',false,'status','complete','percent',100,'stageIndex',5,'currentStage','idle','currentStageLabel','Idle',
      'finishedAt',coalesce(p_status->>'finishedAt',p_stamp::text),'completedAt',p_stamp,'error','','errorCode','','message','Five operational sources completed.');
  end if;
  return p_status||jsonb_build_object('percent',floor(total/(case when p_status->'sourceProgress' ? 'prod_schedule' then 6 else 5 end)))||case when p_status->>'status'='complete' then
    jsonb_build_object('active',true,'status','running','finishedAt',null,'completedAt',null,'message','Continuing unfinished operational sources.') else '{}'::jsonb end;
end $$;

